import os
from taf.ul.sc.util import util
from taf.ul.sc.unix_functionality import UnixFunctionality


class Workstation(UnixFunctionality):
    """Class with keywords for EMSSIM Workstation."""

    def __init__(self,
                 device_name='EMSSIM1_WS',              # type: 'Optional[str]'
                 device=None,                           # type: 'Optional[UnixRemote, UnixLocal]'
                 autoconnect=True,                      # type: 'Optional[bool]'
                 uploads_dir='~/UPLOADS',               # type: 'Optional[str]'
                 packed_pm_stats_name='PMstats.zip',    # type: 'Optional[str]'
                 rise_data_file='rise_pm_data.txt',     # type: 'Optional[str]'
                 rise_data_dir='/opt/emssim/rise',      # type: 'Optional[str]'
                 get_device=False                       # type: 'Optional[bool]'
                 ):
        """
        :param device_name: Moler device name - by default EMSSIM1_WS.
        :param autoconnect: Connect to device after create object.
        :param uploads_dir: Path to UPLOADS directory.
        :param packed_pm_stats_name: Name of archive where pm stats will go after packing them using zip command.
        """
        super(Workstation, self).__init__(device_name=device_name, device=device,
                                          autoconnect=autoconnect, get_device=get_device)
        self.uploads_dir = uploads_dir
        self.pm_dir = os.path.join(self.uploads_dir, 'KEYSTATS')
        self.pm_backup_dir = os.path.join(self.uploads_dir, 'OLD_STATS')
        self.packed_pm_stats_name = packed_pm_stats_name
        self.rise_data_dir = rise_data_dir
        self.rise_data_file = rise_data_file

    def create_pm_backup_directory(self):
        """
        Create pm backup directory for containing old pm stats.

        :return: None
        """
        ls_result = self.device.run(
            cmd_name='ls', cmd_params={'options': "{}".format(self.uploads_dir)})
        if ls_result['files'].get(os.path.basename(self.pm_backup_dir)) is None:
            self.device.run(cmd_name='mkdir', cmd_params={'path': self.pm_backup_dir})

    def remove_pm_backup_directory(self):
        """
        Remove pm backup directory.

        :return: None
        """
        self.device.run(cmd_name='rm',
                        cmd_params={'file': self.pm_backup_dir, 'options': '-r'})

    def backup_pm_files(self):
        """
        Move pm stats files to pm backup directory.

        :return: None
        """
        self.create_pm_backup_directory()
        ls_result = self.device.run(
            cmd_name='ls', cmd_params={'options': "{}".format(self.pm_dir)})
        if len(ls_result["files"]):
            self.device.run(cmd_name='mv', cmd_params={'src': os.path.join(self.pm_dir, "*"),
                                                       'dst': self.pm_backup_dir})

    def collect_pm_files(self, destination_dir):
        """
        SCP pm stats files from EMSSIM workstation to UnixLocal.

        :param destination_dir: Target directory where archive with pm files will be downloaded
        :return: None
        """
        self._pack_pm_files()
        util().download_files(local_dir=destination_dir,
                              remote_file=self.packed_pm_stats_name,
                              remote_dir=self.uploads_dir,
                              remote_device_name=self.name,
                              remove_source_file=True
                              )

    def _pack_pm_files(self):
        """
        Pack backup directory with pm stats files.
        :return:
        """
        zip_cmd = self.device.get_cmd(cmd_name='zip',
                                      cmd_params={'zip_file': os.path.join(self.uploads_dir, self.packed_pm_stats_name),
                                                  'file_name': self.pm_dir, 'options': '-rj'})
        zip_cmd(timeout=180)

    def remove_old_pm_files(self, old_day=7):
        """
        Remove old pm stats files from pm backup directory.

        :param old_day: Files older than specified number of days by this parameter will be removed
        :return: None
        """
        find_result = self.device.run(
            cmd_name='find',
            cmd_params={'paths': [self.pm_backup_dir],
                        'operators': '-mtime +{}'.format(old_day)})

        for pm_file in find_result['RESULT']:
            self.device.run(cmd_name='rm', cmd_params={'file': pm_file})

    def collect_rtpm_data_file(self, destination_dir, rtpm_file=None):
        """
        SCP rtpm data file from EMSSIM workstation to UnixLocal.

        :param destination_dir: Target directory where rtpm file will be downloaded
        :param rtpm_file: path to rtpm file loated on EMSSIM. If not passed default location will be used
        :return: None
        """

        rtpm_file = rtpm_file if rtpm_file else os.path.join(self.pm_dir, "RTPM", "RTPM_Data.pl")

        util().download_files(local_dir=destination_dir,
                              remote_file=os.path.basename(rtpm_file),
                              remote_dir=os.path.dirname(rtpm_file),
                              remote_device_name=self.name,
                              )

    def collect_rise_pm_data(self, destination_dir):
        """
        SCP rise_pm_data file from EMSSIM /opt/emssim/rise/ to UnixLocal.

        :param destination_dir: Target directory where rise_pm_data file will be downloaded
        :return: None
        """
        util().download_files(local_dir=destination_dir,
                              remote_file=self.rise_data_file,
                              remote_dir=self.rise_data_dir,
                              remote_device_name=self.name,
                              remove_source_file=False
                              )
